head.script:
var count = 0;

scwin.trigger1_onclick = function(e) {
	var bFormatter = function() {
		return [
			{
				'id' : 'custombtn',
				'className' : 'w2widget_btnCustom',
				'ariaLabel' : '커스텀버튼1',
				'title' : '커스텀버튼1',
				'isCustom' : true
			},
			{
				'id' : 'custombtn2',
				'className' : 'w2widget_btnCustom',
				'ariaLabel' : '커스텀버튼2',
				'title' : '커스텀버튼2',
				'ariaLabelLocaleRef' : 'widget_btn_aria_label',
				'titleLocaleRef' : 'widget_btn_title',
				'isCustom' : true
			},
			{'useDefault' : 'maximize'},
			{'useDefault' : 'close'}
		];
	};

	count++;
	widgetContainer1.addWidgets({
		id : "widget" + count,
		title : "위젯" + count,
		src : "/sample/common_link/widgetContainer_common_widget.xml",
		scope : true,
		x : 0,
		y : 0,
		unitWidth : 1,
		unitHeight : 1,
		buttonFormatter : bFormatter
	});
};

scwin.checkVal = function() {
	return (document.getElementById('widgetContainer1_widget1_title_custombtn2') || document.getElementById('mf_widgetContainer1_widget1_title_custombtn2')).getAttribute('title') == 'global_undefined';
};
